import { checkRegistry } from '@app/contracts';
import {
  createRoleAuthorizer,
  createTestContext,
  createTestExecutor,
  createTestPrincipal,
  denyAllAuthorizer,
  type TestExecutor,
} from '@app/kernel';
import { describe, expect, it } from 'vitest';

import { createSubject, sampleInput } from './routing-simulate.fixture';
import { routingSimulate } from '@app/contracts';
import { createRoutingSimulateAction } from './routing-simulate';
import { runQuery, type FakeOptions } from './run.fixture';
import type { FakeVhost } from '../testing';

const subject = createSubject;
const { def } = createSubject();
const KEY = 'generated-spec-key-0001';

/** Runs the action as the engine does: a plan first when one is required, then its execution. */
async function runToEnd(engine: TestExecutor) {
  const ctx = createTestContext({ idempotencyKey: KEY });
  const outcome = await engine.executor.run(def, sampleInput, ctx);
  if (outcome.kind !== 'planRequired') return outcome;
  return engine.executor.execute(
    {
      planId: outcome.plan.id,
      consents: [...outcome.plan.consentsRequired],
      confirmation: outcome.plan.confirmationPhrase,
      idempotencyKey: KEY,
    },
    ctx,
  );
}

describe('routing.simulate', () => {
  it('M1-20 G-1 the contract passes the kit invariants and the sample input fits it', () => {
    expect(checkRegistry({ actions: [def], topics: [] })).toEqual([]);
    expect(def.input.safeParse(sampleInput).success).toBe(true);
  });

  it('M1-20 G-3 a principal that does not hold broker.read is refused before anything runs', async () => {
    const engine = createTestExecutor({
      executor: {
        authorizer: createRoleAuthorizer({ operator: ['broker.read'] }),
      },
    });
    engine.executor.register(subject());
    const ctx = createTestContext({
      principal: createTestPrincipal({ roles: ['intruder'] }),
      idempotencyKey: KEY,
    });

    await expect(
      engine.executor.run(def, sampleInput, ctx),
    ).rejects.toMatchObject({ code: 'FORBIDDEN_RBAC' });

    expect(engine.audit.attempts).toEqual([]);
    expect(engine.receipts.records).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('M1-20 G-3 with no authorizer wired every call is refused: deny by default', async () => {
    const engine = createTestExecutor({
      executor: { authorizer: denyAllAuthorizer },
    });
    engine.executor.register(subject());

    await expect(runToEnd(engine)).rejects.toMatchObject({
      code: 'FORBIDDEN_RBAC',
    });

    expect(engine.audit.attempts).toEqual([]);
    expect(engine.writeCalls).toEqual([]);
  });

  it('M1-20 G-3 a principal that holds broker.read is let through', async () => {
    const engine = createTestExecutor({
      executor: {
        authorizer: createRoleAuthorizer({ operator: ['broker.read'] }),
      },
    });
    engine.executor.register(subject());
    const ctx = createTestContext({
      principal: createTestPrincipal({ roles: ['operator'] }),
      idempotencyKey: KEY,
    });

    const outcome = await engine.executor.run(def, sampleInput, ctx);

    expect(['output', 'job', 'planRequired']).toContain(outcome.kind);
  });

  it('M1-20 G-4 a query leaves no audit row and no receipt, and answers in the shape of the contract', async () => {
    const engine = createTestExecutor();
    engine.executor.register(subject());

    const done = await runToEnd(engine);

    if (done.kind !== 'output')
      throw new Error(`expected output, got ${done.kind}`);
    expect(def.output.safeParse(done.output).success).toBe(true);
    expect(engine.audit.attempts).toEqual([]);
    expect(engine.receipts.records).toEqual([]);
  });
});

// --- M1-20 -------------------------------------------------------------------------------------
const answerOf = (
  input: Record<string, unknown>,
  vhost: FakeVhost,
  options: FakeOptions = {},
) =>
  runQuery(
    routingSimulate,
    createRoutingSimulateAction,
    { vhost: '/', ...input },
    { ...options, vhosts: { '/': vhost } },
  );

const queue = (name: string, extra: Record<string, unknown> = {}) => ({
  name,
  type: 'classic',
  policy: null,
  operator_policy: null,
  ...extra,
});

describe('M1-20 AC-4 unroutable key gives the alternate exchange path or unroutable', () => {
  const plain: FakeVhost = {
    exchanges: [{ name: 'orders', type: 'direct' }],
    queues: [queue('q')],
    bindings: [{ source: 'orders', destination: 'q', routing_key: 'a' }],
  };

  it('is unroutable when no binding matches and there is no alternate exchange', async () => {
    const { output } = await answerOf(
      { exchange: 'orders', routingKey: 'zzz' },
      plain,
    );

    expect(output.result).toMatchObject({
      outcome: 'unroutable',
      unroutable: true,
      exact: true,
      queues: [],
      usedAE: false,
    });
    expect(output.gaps).toEqual([]);
  });

  it('is returned to the publisher when the publish is mandatory', async () => {
    const { output } = await answerOf(
      { exchange: 'orders', routingKey: 'zzz', mandatory: true },
      plain,
    );

    expect(output.result).toMatchObject({
      outcome: 'unroutable',
      fate: 'returned',
    });
  });

  it('follows the alternate exchange of an argument and shows the hop', async () => {
    const { output } = await answerOf(
      { exchange: 'orders', routingKey: 'zzz' },
      {
        exchanges: [
          {
            name: 'orders',
            type: 'direct',
            arguments: { 'alternate-exchange': 'unrouted' },
          },
          { name: 'unrouted', type: 'fanout' },
        ],
        queues: [queue('lost')],
        bindings: [{ source: 'unrouted', destination: 'lost' }],
      },
    );

    expect(output.result).toMatchObject({
      outcome: 'routed',
      usedAE: true,
      queues: ['lost'],
    });
    expect(
      output.result.paths[0]?.hops.map((h) => [h.exchange, h.how]),
    ).toEqual([
      ['orders', 'alternate-exchange'],
      ['unrouted', 'binding'],
    ]);
  });

  it('follows an alternate exchange that a policy sets', async () => {
    const { output } = await answerOf(
      { exchange: 'orders', routingKey: 'zzz' },
      {
        exchanges: [
          { name: 'orders', type: 'direct' },
          { name: 'unrouted', type: 'fanout' },
        ],
        queues: [queue('lost')],
        bindings: [{ source: 'unrouted', destination: 'lost' }],
        policies: [
          {
            name: 'ae',
            pattern: '^orders$',
            'apply-to': 'exchanges',
            definition: { 'alternate-exchange': 'unrouted' },
          },
        ],
      },
    );

    expect(output.result).toMatchObject({ usedAE: true, queues: ['lost'] });
  });

  it('does not call a publish unroutable when the policies that could route it were not readable', async () => {
    const { output } = await answerOf(
      { exchange: 'orders', routingKey: 'zzz' },
      { ...plain, policies: 'forbidden' },
    );

    // The library saw a topology without the policy that may set an alternate exchange.
    expect(output.result.outcome).toBe('unroutable');
    expect(output.result.unroutable).toBe(false);
    expect(output.result.exact).toBe(false);
    expect(output.gaps).toContain('policy-unreadable');
  });

  it('routes a direct key, the default exchange by queue name, and the CC and BCC keys', async () => {
    const vhost: FakeVhost = {
      ...plain,
      queues: [queue('q'), queue('other'), queue('hidden')],
      bindings: [
        { source: 'orders', destination: 'q', routing_key: 'a' },
        { source: 'orders', destination: 'other', routing_key: 'b' },
        { source: 'orders', destination: 'hidden', routing_key: 'c' },
      ],
    };

    const direct = await answerOf(
      { exchange: 'orders', routingKey: 'a' },
      vhost,
    );
    const byName = await answerOf({ exchange: '', routingKey: 'other' }, vhost);
    const copies = await answerOf(
      { exchange: 'orders', routingKey: 'a', cc: ['b'], bcc: ['c'] },
      vhost,
    );

    expect(direct.output.result.queues).toEqual(['q']);
    expect(byName.output.result).toMatchObject({ queues: ['other'] });
    expect(byName.output.result.paths[0]?.hops[0]?.how).toBe(
      'default-exchange',
    );
    expect(copies.output.result.queues).toEqual(['hidden', 'other', 'q']);
    expect(copies.output.result.keys).toEqual({
      routingKey: 'a',
      cc: ['b'],
      bcc: ['c'],
    });
  });

  it('matches a headers exchange on the headers given', async () => {
    const { output } = await answerOf(
      { exchange: 'h', routingKey: '', headers: { colour: 'red' } },
      {
        exchanges: [{ name: 'h', type: 'headers' }],
        queues: [queue('red'), queue('blue')],
        bindings: [
          {
            source: 'h',
            destination: 'red',
            arguments: { colour: 'red', 'x-match': 'all' },
          },
          {
            source: 'h',
            destination: 'blue',
            arguments: { colour: 'blue', 'x-match': 'all' },
          },
        ],
      },
    );

    expect(output.result.queues).toEqual(['red']);
  });

  it('refuses an exchange that does not exist with the broker reply code', async () => {
    const { output } = await answerOf(
      { exchange: 'nope', routingKey: 'x' },
      plain,
    );

    expect(output.result).toMatchObject({
      outcome: 'refused',
      refusal: { code: 'exchange-not-found', replyCode: 404 },
    });
  });

  it('cuts a fan-out to more queues than an answer carries, and counts what it cut', async () => {
    const queues = Array.from({ length: 1_200 }, (_, i) =>
      queue(`q${String(i).padStart(4, '0')}`),
    );
    const { output } = await answerOf(
      { exchange: 'fan', routingKey: '' },
      {
        exchanges: [{ name: 'fan', type: 'fanout' }],
        queues,
        bindings: queues.map((q) => ({ source: 'fan', destination: q.name })),
      },
    );

    expect(output.result.queues).toHaveLength(1_000);
    expect(output.result.exact).toBe(false);
    expect(output.result.truncation.queues).toBeGreaterThan(0);
    expect(output.result.paths.length).toBeLessThanOrEqual(2_000);
  });

  it('refuses headers that break the contract', async () => {
    await expect(
      answerOf(
        { exchange: 'orders', routingKey: 'a', cc: Array(65).fill('k') },
        plain,
      ),
    ).rejects.toMatchObject({ code: 'VALIDATION_FAILED' });
  });
});
